const express = require('express');
const crypto = require('crypto');
const app = express();
app.use(express.json());

// In-memory store
const users = new Map();
const sessions = new Map();
const documents = new Map();

// Security: Rate limiting state
const rateLimits = new Map();

function checkRateLimit(ip) {
  const now = Date.now();
  const entry = rateLimits.get(ip) || { count: 0, resetAt: now + 60000 };
  if (now > entry.resetAt) {
    entry.count = 0;
    entry.resetAt = now + 60000;
  }
  entry.count++;
  rateLimits.set(ip, entry);
  return entry.count <= 100;
}

// Access level constants
const ACCESS_LEVELS = {
  NONE: 0,
  READ: 1,
  WRITE: 2,
  ADMIN: 3
};

// Secure password hashing
async function hashPassword(password) {
  const salt = crypto.randomBytes(16).toString('hex');
  return new Promise((resolve, reject) => {
    crypto.scrypt(password, salt, 64, (err, derived) => {
      if (err) return reject(err);
      resolve(salt + ':' + derived.toString('hex'));
    });
  });
}

async function verifyPassword(password, hash) {
  const [salt, key] = hash.split(':');
  return new Promise((resolve, reject) => {
    crypto.scrypt(password, salt, 64, (err, derived) => {
      if (err) return reject(err);
      const keyBuffer = Buffer.from(key, 'hex');
      // timingSafeEqual throws if lengths differ; guard against malformed hashes
      if (keyBuffer.length !== derived.length) {
        return resolve(false);
      }
      resolve(crypto.timingSafeEqual(keyBuffer, derived));
    });
  });
}

// Document access control
function getEffectiveAccessLevel(user, document) {
  // Admin always has full access
  if (user.role === 'admin') return ACCESS_LEVELS.ADMIN;

  // Check document-specific permissions
  const docPerms = document.permissions || {};
  const userPerm = docPerms[user.id];

  // Check group permissions
  const groupPerm = (user.groups || []).reduce((maxLevel, group) => {
    const groupAccess = docPerms['group:' + group];
    // Only consider valid numeric access levels
    if (typeof groupAccess === 'number' && groupAccess >= ACCESS_LEVELS.NONE && groupAccess <= ACCESS_LEVELS.ADMIN) {
      return groupAccess > maxLevel ? groupAccess : maxLevel;
    }
    return maxLevel;
  }, ACCESS_LEVELS.NONE);

  // Return the higher of user-specific and group permissions
  // Ensure both are valid numbers before comparison
  const validUserPerm = (typeof userPerm === 'number' && userPerm >= ACCESS_LEVELS.NONE && userPerm <= ACCESS_LEVELS.ADMIN) ? userPerm : ACCESS_LEVELS.NONE;
  const validGroupPerm = groupPerm; // already validated above

  const effectiveLevel = validUserPerm > validGroupPerm ? validUserPerm : validGroupPerm;

  return effectiveLevel;
}

// Check if user can perform action on document
function authorizeAction(user, document, requiredLevel) {
  const effective = getEffectiveAccessLevel(user, document);
  // Security check: effective level must meet or exceed required
  return effective >= requiredLevel;
}

// Middleware: authenticate session
function authenticate(req, res, next) {
  const token = req.headers['x-session-token'];
  if (!token || typeof token !== 'string' || !sessions.has(token)) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  const session = sessions.get(token);
  if (Date.now() > session.expiresAt) {
    sessions.delete(token);
    return res.status(401).json({ error: 'Session expired' });
  }
  req.user = users.get(session.userId);
  if (!req.user) {
    return res.status(401).json({ error: 'User not found' });
  }
  next();
}

// Register
app.post('/api/register', async (req, res) => {
  if (!checkRateLimit(req.ip)) return res.status(429).json({ error: 'Rate limited' });
  const { username, password } = req.body;
  if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid input' });
  }
  if (username.length < 3 || username.length > 30 || !/^[a-zA-Z0-9_]+$/.test(username)) {
    return res.status(400).json({ error: 'Invalid username' });
  }
  if (password.length < 8 || password.length > 128) {
    return res.status(400).json({ error: 'Invalid password' });
  }

  const existingUser = [...users.values()].find(u => u.username === username);
  if (existingUser) return res.status(409).json({ error: 'Username taken' });

  const id = crypto.randomUUID();
  const hashedPassword = await hashPassword(password);
  users.set(id, { id, username, password: hashedPassword, role: 'user', groups: [] });
  res.status(201).json({ id, username });
});

// Login
app.post('/api/login', async (req, res) => {
  if (!checkRateLimit(req.ip)) return res.status(429).json({ error: 'Rate limited' });
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: 'Invalid input' });

  const user = [...users.values()].find(u => u.username === username);
  if (!user) return res.status(401).json({ error: 'Invalid credentials' });

  const valid = await verifyPassword(password, user.password);
  if (!valid) return res.status(401).json({ error: 'Invalid credentials' });

  const token = crypto.randomBytes(32).toString('hex');
  sessions.set(token, { userId: user.id, expiresAt: Date.now() + 3600000 });
  res.json({ token });
});

// Create document
app.post('/api/documents', authenticate, (req, res) => {
  const { title, content, permissions } = req.body;
  if (!title || typeof title !== 'string') return res.status(400).json({ error: 'Title required' });

  const id = crypto.randomUUID();
  const doc = {
    id,
    title: title.slice(0, 200),
    content: (content || '').slice(0, 10000),
    owner: req.user.id,
    permissions: { [req.user.id]: ACCESS_LEVELS.ADMIN },
    createdAt: new Date().toISOString()
  };

  // Allow setting initial permissions for other users/groups
  if (permissions && typeof permissions === 'object') {
    for (const [key, level] of Object.entries(permissions)) {
      // Validate permission level is a known value
      if (typeof level === 'number' && Number.isInteger(level) && Object.values(ACCESS_LEVELS).includes(level)) {
        doc.permissions[key] = level;
      }
    }
  }

  documents.set(id, doc);
  res.status(201).json({ id, title: doc.title });
});

// Get document - requires READ access
app.get('/api/documents/:id', authenticate, (req, res) => {
  const doc = documents.get(req.params.id);
  if (!doc) return res.status(404).json({ error: 'Not found' });

  if (!authorizeAction(req.user, doc, ACCESS_LEVELS.READ)) {
    return res.status(403).json({ error: 'Access denied' });
  }

  res.json({ id: doc.id, title: doc.title, content: doc.content, owner: doc.owner });
});

// Update document - requires WRITE access
app.put('/api/documents/:id', authenticate, (req, res) => {
  const doc = documents.get(req.params.id);
  if (!doc) return res.status(404).json({ error: 'Not found' });

  if (!authorizeAction(req.user, doc, ACCESS_LEVELS.WRITE)) {
    return res.status(403).json({ error: 'Access denied' });
  }

  if (req.body.title) doc.title = String(req.body.title).slice(0, 200);
  if (req.body.content !== undefined) doc.content = String(req.body.content).slice(0, 10000);

  res.json({ id: doc.id, title: doc.title });
});

// Update document permissions - requires ADMIN access
app.put('/api/documents/:id/permissions', authenticate, (req, res) => {
  const doc = documents.get(req.params.id);
  if (!doc) return res.status(404).json({ error: 'Not found' });

  if (!authorizeAction(req.user, doc, ACCESS_LEVELS.ADMIN)) {
    return res.status(403).json({ error: 'Access denied' });
  }

  const { target, level } = req.body;
  if (!target || typeof target !== 'string') {
    return res.status(400).json({ error: 'Target required' });
  }

  // Validate the level is a recognized access level
  if (typeof level !== 'number' || !Number.isInteger(level) || !Object.values(ACCESS_LEVELS).includes(level)) {
    return res.status(400).json({ error: 'Invalid access level' });
  }

  doc.permissions[target] = level;
  res.json({ success: true });
});

// Admin: manage user groups
app.put('/api/admin/users/:id/groups', authenticate, (req, res) => {
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Admin only' });
  }

  const targetUser = users.get(req.params.id);
  if (!targetUser) return res.status(404).json({ error: 'User not found' });

  const { groups } = req.body;
  if (!Array.isArray(groups)) return res.status(400).json({ error: 'Groups must be array' });

  targetUser.groups = groups.filter(g => typeof g === 'string' && g.length <= 50).slice(0, 20);
  res.json({ success: true, groups: targetUser.groups });
});

